bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
import {mkdtemp,rm,stat,lstat} from 'node:fs/promises';
import {execFile} from 'node:child_process';import {promisify} from 'node:util';
import {setDefaultResultOrder} from 'node:dns';import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from '/opt/videobot/src/telegram/botApi.mjs';
import {createTelegramVideoFetcher} from '/opt/videobot/src/telegram/telegramFileFetch.mjs';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const e=process.env,db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
const network=createCreatorTelegramFetch(),exec=promisify(execFile);
const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
const api=createTelegramBotApi({token,fetchImpl:network.fetch,timeoutMs:25000});
const fetch=createTelegramVideoFetcher({telegramApi:api,token,fetchImpl:network.fetch,maxBytes:19000000});
let dir=null,stage=71;
try{
 const q=await db.query("SELECT l.thumbnail_file_id,l.sample_file_id FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[]");
 if(q.rowCount!==1)throw Error('INPUT_NOT_UNIQUE');
 dir=await mkdtemp('/tmp/gace-video-layout-check-');
 stage=72;const photo=await fetch(q.rows[0].thumbnail_file_id,dir);
 stage=73;const sample=await fetch(q.rows[0].sample_file_id,dir);
 const filter="scale=600:800:force_original_aspect_ratio=decrease,pad=600:800:(ow-iw)/2:(oh-ih)/2:color=black";
 const outputPhoto=dir+'/album-photo.jpg',outputVideo=dir+'/album-video.mp4';
 stage=74;await exec('ffmpeg',['-nostdin','-hide_banner','-loglevel','error','-i',photo.path,'-vf',filter,'-frames:v','1','-q:v','3','-y',outputPhoto],{timeout:45000,maxBuffer:100000});
 stage=75;try{
  await exec('ffmpeg',['-nostdin','-hide_banner','-loglevel','error','-i',sample.path,'-t','2','-map','0:v:0','-map','0:a?','-vf',filter,'-c:v','libx264','-threads','1','-preset','ultrafast','-crf','25','-maxrate','2000k','-bufsize','4000k','-pix_fmt','yuv420p','-c:a','aac','-b:a','96k','-movflags','+faststart','-y',outputVideo],{timeout:60000,maxBuffer:100000});
 }catch(e){
 const t=String(e.stderr||'').toLowerCase();
 if(e.killed||e.signal==='SIGTERM')stage=81;
 else if(t.includes('no space left on device'))stage=82;
 else if(t.includes('unknown encoder'))stage=83;
 else if(t.includes('error while opening encoder'))stage=84;
 else if(t.includes('invalid argument'))stage=85;
 else if(t.includes('resource temporarily unavailable'))stage=86;
 else if(t.includes('conversion failed'))stage=87;
 else stage=88;
 throw e;
 }
 stage=76;for(const f of [outputPhoto,outputVideo]){
  const info=await stat(f);
  if(info.size<100||info.size>19000000)throw Error('PREVIEW_SIZE_OUT_OF_BOUNDS');
  const probe=await exec('ffprobe',['-v','error','-select_streams','v:0','-show_entries','stream=width,height','-of','csv=p=0',f],{timeout:30000,maxBuffer:10000});
  if(probe.stdout.trim()!=='600,800')throw Error('PREVIEW_ASPECT_NOT_PORTRAIT');
 }
 console.log('PRESENTATION_TWO_MEDIA_3_TO_4_WITHOUT_CROPPING=PASS');
 console.log('ORIGINAL_SOURCE_AND_PAID_VIDEO_UNCHANGED=PASS');
}catch(e){console.error('ALBUM_LAYOUT_SAFE_DRY_RUN_STAGE='+stage);process.exitCode=stage;}
finally{if(dir)await rm(dir,{recursive:true,force:true});await network.close();await db.end();}
JS
